-- Base al esquema de V14 (sin las columnas de V15) con una venta real ya
-- facturada, para probar que V15 le agrega las columnas de descuento a
-- detalle_venta sin romper ni tocar lo que ya existia.

create table categoria (id bigint generated by default as identity, descripcion varchar(255), nombre varchar(255), primary key (id));
create table compra (fecha_anulacion timestamp(6), fecha_hora timestamp(6), id bigint generated by default as identity, anulada_por varchar(255), proveedor varchar(255), usuario varchar(255), estado enum ('ACTIVA','ANULADA'), primary key (id));
create table configuracion (ganancia_por_defecto float(53), umbral_stock_bajo float(53), id bigint not null, version bigint, nombre_negocio varchar(255), primary key (id));
create table detalle_compra (cantidad float(53) not null, precio_costo float(53) not null, precio_costo_anterior float(53), subtotal float(53) not null, compra_id bigint, id bigint generated by default as identity, producto_id bigint, primary key (id));
create table detalle_venta (cantidad float(53) not null, precio_costo float(53) not null, precio_unitario float(53) not null, subtotal float(53) not null, id bigint generated by default as identity, producto_id bigint, venta_id bigint, primary key (id));
create table producto (activo boolean not null, fraccion_minima float(53), porcentaje_ganancia float(53) not null, precio_costo float(53) not null, precio_venta float(53) not null, stock float(53) not null, unidades_por_paquete integer, categoria_id bigint, id bigint generated by default as identity, version bigint, codigo_barras varchar(255), imagen_url varchar(255), nombre varchar(255), proveedor varchar(255), tipo_cantidad varchar(255) not null, unidad_medida varchar(255), primary key (id));
create table promocion (activo boolean not null, cantidad_lleva integer not null, cantidad_paga integer not null, id bigint generated by default as identity, producto_id bigint, primary key (id));
create table usuario (id bigint generated by default as identity, nombre varchar(255), password varchar(255), rol varchar(255), username varchar(255) unique, primary key (id));
create table venta (total float(53) not null, fecha_anulacion timestamp(6), fecha_hora timestamp(6), id bigint generated by default as identity, anulada_por varchar(255), usuario varchar(255), estado enum ('ACTIVA','ANULADA') not null, primary key (id));
create unique index ux_producto_codigo_barras on producto(codigo_barras);

